node -e "
const Database = require('better-sqlite3');
const { v4: uuidv4 } = require('uuid');
const db = new Database('/workspace/world.db');

const reminderId = uuidv4();
const content = 'Follow up with Monica Reyes regarding the vendor escalation.';
const creationTimestamp = Date.now() / 1000;
const reminderTimestamp = 1788361200; // 2026-09-02 10:00:00 EST

db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude) VALUES (?, ?, ?, ?, NULL, NULL)')
  .run(reminderId, content, creationTimestamp, reminderTimestamp);

// Verify it was created
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log(JSON.stringify(row, null, 2));
" 2>&1

